// 一次性探针（只读）: "标签搬进模板"到底能不能做到 I3 逐字节？
//
// 为什么必须验（#265 ④ 要求"默认模板产物逐字节不变"）:
//   `渲染段` 的规则决定了换行从哪来：
//     ① 整行占位符 → 用它的值，**这一行前面的换行丢掉**
//     ④ 普通行 → 前面补一个 `\n`
//     ②b 行内占位符为空 → 整行消失（连同行内文字）
//
//   原产物里，`\n\n` + 标签 + `\n` + 数据 **全在占位符内容里**（规则 ① 原样输出）。
//   标签一搬出去，那些换行就得由模板结构产生 —— 而模板结构每行只能产生一个 `\n`。
//
// 本探针跑三种候选方案，逐一报"两种场景（有值/空值）下是否逐字节"：
//   B  拆成两个占位符：`X·标签`（条件为空）+ `X`（纯数据）
//   C  标签写成模板文字，占位符保留 `\n\n` 前缀
//   C2 标签写成模板文字，占位符改成 `\n` 前缀
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildTest } from '../build.mjs';
import path from 'node:path';

const 此处 = path.dirname(fileURLToPath(import.meta.url));
const 入口 = path.join(此处, '_probe-ways.ts');
const 产物 = path.join(此处, '_probe-ways.mjs');

const 源码 = [
  "import { buildUpdateMessages } from '../../src/彼方_NPC幕后生命状态系统/prompts';",
  "import { 默认模板, 渲染段 } from '../../src/彼方_NPC幕后生命状态系统/提示词模板';",
  "",
  "const 造 = (额外 = {}) => ({",
  "  reply: '这是第一段正文。\\n\\n这是第二段正文，结尾在这里。', replyCount: 2,",
  "  context: '玩家的输入', timeJump: '无',",
  "  tracked: ['甲'], inSceneHint: ['乙'],",
  "  currentCards: { 甲: { 当前在做: '做饭', 当前状态: '平静', 位置: '家', 身份锚点: '面包师' } },",
  "  autoTrackEnabled: true, physioEnabled: false, 恋爱对象名单: [], 自定义段: [],",
  "  预填充: false, worldbook: '世界书正文内容', currentStoryTime: '2026-01-01 20:00',",
  "  storyTimeHint: '2026-01-02 12:30', storySpan: '约 0.7 天',",
  "  recentTrace: '甲: 从广场走到家',",
  "  playerName: '主角', playerDescription: '主角的描述文本', 展开宏: (t) => t,",
  "  模板: 默认模板, ...额外,",
  "});",
  "",
  "const 跑 = (额外) => {",
  "  const 原I = console.info, 原T = console.table, 原W = console.warn;",
  "  console.info = () => {}; console.table = () => {}; console.warn = () => {};",
  "  let r;",
  "  try { r = buildUpdateMessages(造(额外)); }",
  "  finally { console.info = 原I; console.table = 原T; console.warn = 原W; }",
  "  return r;",
  "};",
  "",
  "/** 把某零件切成「标签前缀 / 数据本体」。切点 = 第一个 `):\\n`（含） */",
  "function 切(s) {",
  "  const i = s.indexOf('):\\n');",
  "  if (i < 0) return { 标签: '', 数据: s };",
  "  return { 标签: s.slice(0, i + 3), 数据: s.slice(i + 3) };",
  "}",
  "",
  "/** 取 user 段的前 8 个数据零件部分（D14 骨架之后不算） */",
  "function 前8(user) {",
  "  const i = user.indexOf('**更新 NPC 状态时');",
  "  return i < 0 ? user : user.slice(0, i);",
  "}",
  "",
  "const 名表 = { '最近正文回复': 'D1', '世界书': 'D2', '时间': 'D-T', '名单': 'D-N',",
  "  '主角信息': 'D9', '现有状态卡': 'D10', '台账账况': 'D11', '近期轨迹': 'D12' };",
  "",
  "for (const 场景 of [{ 名: '有值', 额外: {} }, { 名: '世界书为空', 额外: { worldbook: '' } }]) {",
  "  const 产物 = 跑(场景.额外);",
  "  const 原 = 前8(String(产物.messages.find(m => m.role === 'user')?.content ?? ''));",
  "  const 零件 = 产物.零件内容;",
  "",
  "  const d2 = String(零件['D2'] ?? '');",
  "  const d9 = String(零件['D9'] ?? '');",
  "  const d10 = String(零件['D10'] ?? '');",
  "  const 切2 = 切(d2), 切9 = 切(d9), 切10 = 切(d10);",
  "",
  "  console.log('');",
  "  console.log('================ 场景: ' + 场景.名 + ' ================');",
  "  console.log('  原前8段 ' + 原.length + ' 字');",
  "",
  "  // ── 方案 B：拆成 标签占位符 + 数据占位符 ──",
  "  {",
  "    const 新零件 = { ...零件,",
  "      'D2': 切2.数据, 'D2·标签': 切2.数据 ? 切2.标签 : '',",
  "      'D9': 切9.数据, 'D9·标签': 切9.数据 ? 切9.标签 : '',",
  "      'D10': 切10.数据, 'D10·标签': 切10.数据 ? 切10.标签 : '',",
  "    };",
  "    const 新模板 = [",
  "      '{{彼方:最近正文回复}}',",
  "      '{{彼方:世界书·标签}}',",
  "      '{{彼方:世界书}}',",
  "      '{{彼方:时间}}',",
  "      '{{彼方:名单}}',",
  "      '{{彼方:主角信息·标签}}',",
  "      '{{彼方:主角信息}}',",
  "      '{{彼方:现有状态卡·标签}}',",
  "      '{{彼方:现有状态卡}}',",
  "      '{{彼方:台账账况}}',",
  "      '{{彼方:近期轨迹}}',",
  "    ].join('\\n');",
  "    const 新 = 渲染段(新模板, (名) => {",
  "      if (名.endsWith('·标签')) return 新零件[名表[名.replace('·标签', '')] + '·标签'] ?? '';",
  "      return 新零件[名表[名]] ?? '';",
  "    });",
  "    console.log('');",
  "    console.log('  方案 B（拆两个占位符）: ' + 新.length + ' 字，逐字节? ' + (新 === 原));",
  "    if (新 !== 原) {",
  "      let i = 0; while (i < 原.length && i < 新.length && 原[i] === 新[i]) i++;",
  "      console.log('    差异位置 ' + i);",
  "      console.log('      原: ' + JSON.stringify(原.slice(Math.max(0,i-25), i+25)));",
  "      console.log('      新: ' + JSON.stringify(新.slice(Math.max(0,i-25), i+25)));",
  "    }",
  "  }",
  "",
  "  // ── 方案 C：标签写成模板文字，占位符保留 \\n\\n ──",
  "  {",
  "    const 新零件 = { ...零件, 'D2': 切2.数据, 'D9': 切9.数据, 'D10': 切10.数据 };",
  "    // 标签去掉前导 \\n\\n（模板自己会有换行）",
  "    const 标2 = 切2.标签.replace(/^\\n+/, '').replace(/\\n$/, '');",
  "    const 标9 = 切9.标签.replace(/^\\n+/, '').replace(/\\n$/, '');",
  "    const 标10 = 切10.标签.replace(/^\\n+/, '').replace(/\\n$/, '');",
  "    const 新模板 = [",
  "      '{{彼方:最近正文回复}}',",
  "      标2 + '{{彼方:世界书}}',",
  "      '{{彼方:时间}}',",
  "      '{{彼方:名单}}',",
  "      标9 + '{{彼方:主角信息}}',",
  "      标10 + '{{彼方:现有状态卡}}',",
  "      '{{彼方:台账账况}}',",
  "      '{{彼方:近期轨迹}}',",
  "    ].join('\\n');",
  "    const 新 = 渲染段(新模板, (名) => 新零件[名表[名]] ?? '');",
  "    console.log('');",
  "    console.log('  方案 C（标签文字 + 占位符保留 \\\\n\\\\n）: ' + 新.length + ' 字，逐字节? ' + (新 === 原));",
  "    if (新 !== 原) {",
  "      let i = 0; while (i < 原.length && i < 新.length && 原[i] === 新[i]) i++;",
  "      console.log('    差异位置 ' + i);",
  "      console.log('      原: ' + JSON.stringify(原.slice(Math.max(0,i-25), i+25)));",
  "      console.log('      新: ' + JSON.stringify(新.slice(Math.max(0,i-25), i+25)));",
  "      // 可见文字是否相同（去掉所有换行后比）",
  "      const 去换行 = (s) => s.replace(/\\n+/g, '');",
  "      console.log('    可见文字（去换行）相同? ' + (去换行(原) === 去换行(新)));",
  "    }",
  "  }",
  "",
  "  // ── 方案 C2：标签文字 + 占位符改成 \\n 前缀 ──",
  "  {",
  "    const 新零件 = {",
  "      ...零件,",
  "      'D2': 切2.数据 ? '\\n' + 切2.数据 : '',",
  "      'D9': 切9.数据 ? '\\n' + 切9.数据 : '',",
  "      'D10': 切10.数据 ? '\\n' + 切10.数据 : '',",
  "    };",
  "    const 标2 = 切2.标签.replace(/^\\n+/, '').replace(/\\n$/, '');",
  "    const 标9 = 切9.标签.replace(/^\\n+/, '').replace(/\\n$/, '');",
  "    const 标10 = 切10.标签.replace(/^\\n+/, '').replace(/\\n$/, '');",
  "    // 空行 + 标签行（空行为了补第二个 \\n）",
  "    const 新模板 = [",
  "      '{{彼方:最近正文回复}}',",
  "      '',",
  "      标2 + '{{彼方:世界书}}',",
  "      '{{彼方:时间}}',",
  "      '{{彼方:名单}}',",
  "      '',",
  "      标9 + '{{彼方:主角信息}}',",
  "      '',",
  "      标10 + '{{彼方:现有状态卡}}',",
  "      '{{彼方:台账账况}}',",
  "      '{{彼方:近期轨迹}}',",
  "    ].join('\\n');",
  "    const 新 = 渲染段(新模板, (名) => 新零件[名表[名]] ?? '');",
  "    console.log('');",
  "    console.log('  方案 C2（空行 + 标签文字 + \\\\n 前缀）: ' + 新.length + ' 字，逐字节? ' + (新 === 原));",
  "    if (新 !== 原) {",
  "      let i = 0; while (i < 原.length && i < 新.length && 原[i] === 新[i]) i++;",
  "      console.log('    差异位置 ' + i);",
  "      console.log('      原: ' + JSON.stringify(原.slice(Math.max(0,i-25), i+25)));",
  "      console.log('      新: ' + JSON.stringify(新.slice(Math.max(0,i-25), i+25)));",
  "    }",
  "  }",
  "}",
].join('\n');

writeFileSync(入口, 源码);

await buildTest(入口, 产物);
await import(new URL(`file:///${产物.replace(/\\/g, '/')}`).href);
